29	/**
30	 * @brief OperationOutcome - Ergebnis EINER Engine-Operation in der Workload-Loop
31	 * @subsystem CEB
32	 *
33	 * Wird vom EngineCallable pro Operation an die Loop zurueckgegeben. Erlaubt
34	 * der Engine, Mess-Daten ueber den Funktor-Mechanismus zurueckzugeben ohne dass
35	 * die ICommand-Schicht auf konkrete Engine-Typen abhaengt.
36	 */
37	struct OperationOutcome {
38	    std::uint64_t cache_misses_delta{0}; ///< Cache-Misses durch diese Op (z.B. via perf_event)
39	    std::uint64_t bytes_touched{0};      ///< Memory-Traffic dieser Op
40	    bool          success{true};
41	};
