43	/**
44	 * @brief EngineCallable - injizierbare Engine-Operation
45	 * @subsystem CEB
46	 *
47	 * Signature: (op_index, workload_kind, seed) -> OperationOutcome
48	 * Cache-Engine/PrtArt-Adapter implementieren dies + reichen es an
49	 * ExecuteEngineCommand. Nullptr bzw. leerer Funktor -> Simulation (V32-Pfad).
50	 */
51	using EngineCallable = std::function<OperationOutcome(std::size_t, WorkloadKind, std::uint64_t)>;
