53	/**
54	 * @brief ExecuteEngineCommand - fuehrt eine ExecutionEngine auf einer Permutation aus
55	 * @subsystem CEB
56	 * @command_pattern Execute
57	 * @phase_owner CEB
58	 *
59	 * Wird vom CacheEngineBuilder pro ExecutionEngine (EE-A = CacheEngine, EE-B = PrtArt)
60	 * pro Permutation instanziiert + ausgefuehrt. Resultat wird in result_ gespeichert
61	 * und vom CompareEngineCommand verglichen.
62	 *
63	 * V33.A.1: Echte Engine-Integration via EngineCallable (Dependency-Injection).
64	 * Wenn engine_callable_ leer -> Simulation (V32-Pfad, rueckwaertskompatibel).
65	 * Wenn gesetzt -> echte Operation pro Schritt, echte p50/p99 via percentile-Berechnung.
66	 *
67	 * Beispiel-Nutzung mit echtem Engine-Callable:
68	 *   auto ce_callable = [&ce](std::size_t op, WorkloadKind wk, std::uint64_t seed) {
69	 *       std::uint64_t key = derive_key(op, seed);
70	 *       auto result = ce.lookup(key);
71	 *       return OperationOutcome{result.cache_misses, result.bytes_read, result.found};
72	 *   };
73	 *   ExecuteEngineCommand cmd("CacheEngine-EE-A", workload, ce_callable);
74	 *   cmd.execute();
75	 */
76	class ExecuteEngineCommand : public ICommand {
77	public:
78	    /// V32 Konstruktor (Simulation, rueckwaertskompatibel)
79	    ExecuteEngineCommand(std::string_view engine_name, Workload workload) noexcept
80	        : engine_name_{engine_name}, workload_{workload} {}
81	
82	    /// V33.A.1 Konstruktor mit echtem Engine-Callable
83	    ExecuteEngineCommand(std::string_view engine_name, Workload workload, EngineCallable callable) noexcept
84	        : engine_name_{engine_name}, workload_{workload}, engine_callable_{std::move(callable)} {}
85	
86	    [[nodiscard]] std::string_view command_name() const noexcept override { return "ExecuteEngineCommand"; }
87	
88	    int execute() override {
89	        result_.engine_name   = engine_name_;
90	        result_.workload_kind = workload_.kind;
91	
92	        std::vector<std::int64_t> op_latencies_ns;
93	        op_latencies_ns.reserve(workload_.operation_count);
94	
95	        std::uint64_t cache_misses_total  = 0;
96	        std::uint64_t bytes_touched_total = 0;
97	        std::uint64_t ops_succeeded       = 0;
98	
99	        const auto overall_start = std::chrono::steady_clock::now();
100	
101	        for (std::size_t op = 0; op < workload_.operation_count; ++op) {
102	            const auto op_start = std::chrono::steady_clock::now();
103	
104	            OperationOutcome outcome{};
105	            if (engine_callable_) {
106	                outcome = engine_callable_(op, workload_.kind, workload_.seed);
107	            } else {
108	                outcome.cache_misses_delta = (op % 7 == 0) ? 1u : 0u;
109	                outcome.bytes_touched      = 64;
110	                outcome.success            = true;
111	            }
112	
113	            const auto op_end = std::chrono::steady_clock::now();
114	            const auto op_ns  = std::chrono::duration_cast<std::chrono::nanoseconds>(op_end - op_start).count();
115	            op_latencies_ns.push_back(op_ns);
116	
117	            cache_misses_total += outcome.cache_misses_delta;
118	            bytes_touched_total += outcome.bytes_touched;
119	            ops_succeeded += outcome.success ? 1u : 0u;
120	        }
121	
122	        const auto overall_elapsed = std::chrono::steady_clock::now() - overall_start;
123	        const auto overall_ns      = std::chrono::duration_cast<std::chrono::nanoseconds>(overall_elapsed).count();
124	
125	        result_.throughput_ops_per_sec =
126	            (overall_ns > 0) ? (static_cast<double>(workload_.operation_count) * 1e9 / static_cast<double>(overall_ns))
127	                             : 0.0;
128	
129	        // R5.E: geteilte, non-mutierende Perzentile (op_latencies_ns bleibt in Original-Reihenfolge
130	        // → unten als latency_samples_ns fuer Welch's t-Test gemovet).
131	        result_.latency_p50            = stats::percentile_ns(std::span<const std::int64_t>{op_latencies_ns}, 0.50);
132	        result_.latency_p99            = stats::percentile_ns(std::span<const std::int64_t>{op_latencies_ns}, 0.99);
133	        result_.total_cache_misses     = cache_misses_total;
134	        result_.memory_footprint_bytes = engine_callable_ ? bytes_touched_total : workload_.record_count * 64;
135	
136	        // V33.A.2: Latency-Samples behalten fuer Welch's t-Test in CompareEngineCommand
137	        result_.latency_samples_ns = std::move(op_latencies_ns);
138	
139	        // Anti-Phantom (Review 2026-07-12, Ledger §G2): FRUEHER wurden hier H1/H2/H3 UNBEDINGT auf
140	        // 1.0/1.0/0.5 hartkodiert — auch im echten engine_callable_-Pfad. Das war eine Schein-Validierung:
141	        // CompareEngineCommand::hX_validated() (>=1.0 bzw. [0.2,0.8]) lieferte damit INPUT-UNABHAENGIG
142	        // immer `true`, obwohl nichts gemessen wurde. Die drei F15-Struktur-Hypothesen H1
143	        // (Cache-Line-Utilization), H2 (Layout-Score) und H3 (Inline/External-Ratio) sind STRUKTURELLE /
144	        // compile-time-Eigenschaften der Achsen-Konfiguration und in dieser Runtime-Workload-Loop (die nur
145	        // throughput/latency/cache-misses/footprint misst; EngineCallable liefert nur
146	        // cache_misses_delta/bytes_touched/success) NICHT ehrlich ableitbar. Daher bleiben sie beim
147	        // ehrlichen not-measured-Default (0.0 aus ExecutionResult) statt fabrizierter Werte. Folge:
148	        // hX_validated() liefert ehrlich `false` ("nicht validiert / keine Daten") statt Schein-`true`.
149	        // Sobald ein Mess-/Struktur-Konsument H1/H2/H3 REAL liefert, werden sie HIER aus echten Daten
150	        // gesetzt (nicht wieder pauschal). Struct-Default 0.0 => keine explizite Zuweisung noetig.
151	
152	        result_.success = (ops_succeeded == workload_.operation_count);
153	        return result_.success ? 0 : 1;
154	    }
